create table xxventuri.eba_sales_customers (
    id                         number,
    row_version_number         number,
    row_key                    varchar2(255 byte),
    customer_name              varchar2(255 byte),
    tags                       varchar2(4000 byte),
    default_rep_id             number,
    customer_sic               varchar2(30 byte),
    customer_duns              varchar2(30 byte),
    customer_web_site          varchar2(512 byte),
    customer_stock_symb        varchar2(30 byte),
    customer_number_of_emp     number,
    customer_is_public_comp_yn varchar2(1 byte),
    customer_facebook          varchar2(1000 byte),
    customer_linkedin          varchar2(1000 byte),
    customer_twitter           varchar2(1000 byte),
    customer_description       varchar2(4000 byte),
    customer_territory_id      number,
    customer_is_key_account_yn varchar2(1 byte) not null disable,
    created_by                 varchar2(255 byte),
    created                    timestamp(6) with local time zone,
    updated_by                 varchar2(255 byte),
    updated                    timestamp(6) with local time zone,
    internal_flex_flag_01      varchar2(30 byte),
    internal_flex_flag_02      varchar2(30 byte),
    internal_flex_flag_03      varchar2(30 byte),
    internal_flex_flag_04      varchar2(30 byte),
    internal_flex_01           varchar2(4000 byte),
    internal_flex_02           varchar2(4000 byte),
    internal_flex_03           varchar2(4000 byte),
    internal_flex_04           varchar2(4000 byte),
    flex_flag_01               varchar2(30 byte),
    flex_flag_02               varchar2(30 byte),
    flex_flag_03               varchar2(30 byte),
    flex_flag_04               varchar2(30 byte),
    flex_flag_05               varchar2(30 byte),
    flex_flag_06               varchar2(30 byte),
    flex_flag_07               varchar2(30 byte),
    flex_flag_08               varchar2(30 byte),
    flex_01                    varchar2(4000 byte),
    flex_02                    varchar2(4000 byte),
    flex_03                    varchar2(4000 byte),
    flex_04                    varchar2(4000 byte),
    flex_05                    varchar2(4000 byte),
    flex_06                    varchar2(4000 byte),
    flex_07                    varchar2(4000 byte),
    flex_08                    varchar2(4000 byte),
    flex_d01                   timestamp(6) with local time zone,
    flex_d02                   timestamp(6) with local time zone,
    flex_d03                   timestamp(6) with local time zone,
    flex_d04                   timestamp(6) with local time zone,
    flex_n01                   number,
    flex_n02                   number,
    flex_n03                   number,
    flex_n04                   number,
    flex_n05                   number,
    flex_n06                   number,
    flex_n07                   number,
    flex_n08                   number,
    account_source             varchar2(100 byte),
    gst_no                     varchar2(100 byte),
    industry_id                number,
    classification_id          number,
    pan_number                 varchar2(50 byte),
    phone_number               varchar2(50 byte),
    mobile_number              number,
    email_address              varchar2(100 byte),
    customer_code              varchar2(20 byte),
    last_updated_latitude      varchar2(100 byte),
    last_updated_longitude     varchar2(100 byte),
    status                     varchar2(10 byte),
    verified_on                date,
    verified_by                number,
    verify_comments            varchar2(200 byte),
    team_lead_comments         varchar2(200 byte),
    team_lead_id               number,
    details_required           varchar2(200 byte),
    annual_pur_potential_amt   number
);

alter table xxventuri.eba_sales_customers
    add constraint eba_sales_cust_ck_key_acct
        check ( customer_is_key_account_yn in ( 'Y', 'N' ) ) enable;

alter table xxventuri.eba_sales_customers add primary key ( id )
    using index enable;


